"""Rebuild the delivery-map prototype from the original assignment CSV."""
from pathlib import Path
import csv, html, json, os, subprocess, sys
from refined_layout import refine
from map_layout import map_html

ROOT=Path(__file__).resolve().parent
DATA=list(csv.DictReader((ROOT.parent/'docs/assignment/deliveries.csv').open(newline='')))
for i,s in enumerate(DATA):
    s.update(index=i+1,latitude=float(s['latitude']),longitude=float(s['longitude']))
(ROOT/'assets').mkdir(exist_ok=True)
(ROOT/'vendor').mkdir(exist_ok=True)
if not (ROOT/'vendor/alpine.min.js').is_file():
    raise SystemExit('Missing vendored Alpine.js; restore prototype/vendor/alpine.min.js from the repository.')
icon_path=ROOT/'assets/icons.json'
if not icon_path.is_file():
    raise SystemExit('Missing cached icons; restore prototype/assets/icons.json from the repository.')
ICON=json.loads(icon_path.read_text())
def icon(name):return ICON[name]
def esc(value):return html.escape(str(value),quote=True)
def status_icons(expr):
    return ''.join(f'<span x-show="{expr} === \'{status}\'">{icon(name)}</span>' for status,name in [('pending','clock'),('completed','checkcircle'),('failed','warning')])

def row(s,kind=''):
    ref=s['reference'];st=s['status'];n=s['index'];classes='stop-row '+kind
    conditions=[f"visible('{ref}')"]
    if kind=='compact-row':conditions.append(f"(focusAll || selectedId !== '{ref}')")
    condition=' && '.join(conditions)
    return f'''<button id="stop-{ref}" class="{classes}" data-ref="{ref}" x-show="{condition}" @click="openStop('{ref}')" aria-label="Open {esc(s['customer_name'])}, {ref}">
    <span class="stop-index mono">{n:02}</span><span class="stop-content"><h3>{esc(s['customer_name'])}</h3><span class="address">{esc(s['address'])}</span><span class="row-meta"><span class="ref mono">{ref}</span><span class="status {st}" :class="status('{ref}')">{status_icons(f"status('{ref}')")}<span x-text="label(status('{ref}'))">{st.capitalize()}</span></span><span class="row-queue" x-cloak x-show="isQueued('{ref}')">{icon('cloud')}<span>Waiting to sync</span></span></span>{('<span class="time-label" style="margin-top:8px">'+icon('clock')+esc(s['time_window'].replace('-','–'))+'</span>') if not kind else ''}</span>{icon('arrow').replace('<svg ','<svg class="stop-arrow" ')}</button>'''

filter_markup='''<div class="filter" role="group" aria-label="Filter stops by status" :style="'--filter-index:'+filterIndex"><span class="filter-indicator" aria-hidden="true"></span>'''+''.join(f'''<button data-filter="{s}" :class="{{selected: filter === '{s}'}}" :aria-pressed="filter === '{s}'" @click="filter='{s}'">{name}</button>''' for s,name in [('all','All'),('pending','Pending'),('completed','Done'),('failed','Failed')])+'''</div>'''
progress='''<div class="progress-track" aria-label="Stops processed"><span class="progress-part completed" :style="'width:'+count('completed')/30*100+'%'"></span><span class="progress-part failed" :style="'width:'+count('failed')/30*100+'%'"></span><span class="progress-part remaining"></span></div>'''
search=f'''<div class="search">{icon('search')}<input type="search" x-model="search" placeholder="Find a customer or reference" aria-label="Find a customer or reference"></div>'''

list_view=f'''<section class="view" x-show="page === 'stops'" aria-label="Stops"><div class="page-heading"><div><h1>Today's stops</h1><p class="heading-sub">Sydney, NSW <span aria-hidden="true">·</span> <strong>30 stops</strong></p></div><div class="progress-fraction"><strong x-text="count('completed')+count('failed')">6</strong> / 30</div></div>{progress}{filter_markup}{search}<div class="list-heading"><strong x-text="visibleCount + ' '+(filter === 'all'?'stops':filter+' stops')">24 pending stops</strong><span>CSV order</span></div><div class="stops-list">{''.join(row(s) for s in DATA)}</div><div class="empty" x-cloak x-show="visibleCount === 0"><h3>No matching stops</h3><p>Try another status or search term.</p></div></section>'''

focus_view=f'''<section class="view" x-show="page === 'stops'" aria-label="Stops"><div class="focus-summary"><div><h1>Your delivery run</h1><p>Sydney, NSW <span aria-hidden="true">·</span> 30 stops</p></div><div class="focus-count"><strong x-text="count('pending')">24</strong>remaining</div></div>{progress}<article class="focus-stop"><div class="focus-stop-top"><span>Selected stop <strong class="mono" x-text="String(selected.index).padStart(2,'0')">02</strong></span><span class="mono" x-text="selected.reference">TV-300002</span></div><h2 x-text="selected.customer_name">Silverline Supplies</h2><p class="focus-address"><span style="color:var(--ink);font-size:17px" x-text="street">215 Pitt St</span><span x-text="locality">Newtown NSW</span></p><div class="focus-time"><span>Delivery window</span><strong class="mono" x-text="selected.time_window?.replace('-','–')">08:00–10:00</strong></div><div class="focus-actions"><div x-show="selected.status === 'pending'"><button class="primary complete-focus" @click="update('completed')">{icon('check')}Complete delivery</button><button class="secondary fail-focus" @click="openFailure()">{icon('warning')}Report a failed delivery</button></div><div class="focus-final" x-cloak x-show="selected.status !== 'pending'" :class="{{failed:selected.status === 'failed'}}">{icon('checkcircle')}<span x-text="label(selected.status)"></span></div><button x-cloak x-show="selected.status !== 'pending' && count('pending') > 0" class="primary" @click="chooseNext()" style="margin-top:11px">Select another pending stop {icon('arrow')}</button><div x-cloak x-show="saveError" class="save-error" style="margin:15px 0 0" role="alert" x-text="saveError"></div></div></article><div class="focus-list-heading"><span x-text="focusAll?'All pending stops':'Other pending stops'">Other pending stops</span><button @click="focusAll=!focusAll" x-text="focusAll?'Show less':'View all'">View all</button></div><div class="stops-list">{''.join(row(s,'compact-row') for s in DATA)}</div></section>'''

times=['08:00-10:00','10:00-12:00','12:00-14:00','14:00-16:00','16:00-18:00']
groups=''
for t in times:
    start,end=t.split('-')
    groups+=f'''<section x-show="windowFilter === 'all' || windowFilter === '{t}'" aria-label="Delivery window {t}"><div class="window-group-head"><div><div class="window-time mono">{start}</div><div class="window-end">until {end}</div></div><span class="window-line"></span><span class="window-count" x-text="windowCount('{t}')+' stops'">{sum(s['time_window']==t and s['status']=='pending' for s in DATA)} stops</span></div>{''.join(row(s,'window-row') for s in DATA if s['time_window']==t)}<div x-cloak x-show="windowCount('{t}') === 0" class="queue-empty">No stops with this status in this window.</div></section>'''
windows_view=f'''<section class="view" x-show="page === 'stops'" aria-label="Stops"><div class="page-heading window-heading"><div><h1>Delivery windows</h1><p class="heading-sub"><strong x-text="count('pending')">24</strong> pending <span aria-hidden="true">·</span> 5 time windows</p></div>{icon('clock')}</div>{filter_markup}<div class="time-window-tabs" role="group" aria-label="Delivery time window"><button :class="{{selected:windowFilter === 'all'}}" @click="windowFilter='all'">All</button>'''+''.join(f'''<button :class="{{selected:windowFilter === '{t}'}}" @click="windowFilter='{t}'">{t[:2]}–{t[6:8]}</button>''' for t in times)+f'''</div>{groups}</section>'''

sync_view=f'''<section class="view" x-cloak x-show="page === 'sync'" aria-label="Sync queue"><div class="sync-heading"><h1>Sync centre</h1><p>Delivery updates, kept safe on your device.</p></div><div class="sync-hero"><div class="sync-hero-top"><span class="sync-emblem" :class="{{waiting:queue.length&&!syncing,running:syncing,rotating:syncing}}"><span x-show="queue.length || syncing">{icon('sync')}</span><span x-show="!queue.length && !syncing">{icon('checkcircle')}</span></span><div><h2 x-text="syncTitle">Everything is up to date</h2><p x-text="syncSub">No pending updates on this device.</p></div></div><div class="sync-controls"><span>Connection</span><button class="connection sync-toggle" :class="{{offline:!online}}" @click="toggleOnline()" role="switch" :aria-checked="online" aria-label="Online connection"><span class="connection-dot"></span><span x-text="online?'Online':'Offline'">Online</span><span class="switch" :class="{{on:online}}"></span></button></div></div><div x-cloak x-show="saveError" class="save-error" role="alert" x-text="saveError"></div><div class="sync-summary"><h3>Waiting to sync</h3><span x-text="queue.length+' updates'">0 updates</span></div><template x-for="event in queue" :key="event.reference"><article class="queue-row"><span class="queue-icon" :class="{{failed:event.status==='failed'}}"><span x-show="event.status==='completed'">{icon('check')}</span><span x-show="event.status==='failed'">{icon('warning')}</span></span><div class="queue-text"><h3 x-text="stops.find(s=>s.reference===event.reference)?.customer_name"></h3><p><span class="mono" x-text="event.reference"></span> <span aria-hidden="true">·</span> <span x-text="label(event.status)"></span></p><p x-show="event.reason" x-text="event.reason"></p></div><span class="queue-state" x-text="syncing&&queue[0]===event?'Sending':'Saved'"></span></article></template><p x-show="!queue.length" class="queue-empty">Your queue is clear.</p><div class="sync-bottom">{icon('shield')}<span>Your saved updates stay here until they are sent. Reconnecting sends them automatically.</span></div><div x-cloak x-show="history.length"><div class="history-heading">Recently synced</div><template x-for="event in history" :key="event.reference"><article class="queue-row"><span class="queue-icon">{icon('checkcircle')}</span><div class="queue-text"><h3 x-text="stops.find(s=>s.reference===event.reference)?.customer_name"></h3><p><span class="mono" x-text="event.reference"></span> <span aria-hidden="true">·</span> <span x-text="label(event.status)"></span></p></div><span class="status completed" x-text="time(event.syncedAt)"></span></article></template></div></section>'''

detail=f'''<section class="detail-overlay" x-cloak x-show="detailOpen" x-transition:enter="" x-transition:enter-start="" x-transition:enter-end="" x-transition:leave="" role="region" aria-label="Stop details" x-transition:enter.duration.320ms x-transition:leave.duration.190ms><header class="detail-head"><button class="back-label icon-button" style="width:auto;padding:0 8px" x-ref="backButton" @click="closeDetail()">{icon('back')}Stops</button><span class="status" :class="selected.status">{status_icons('selected.status')}<span x-text="label(selected.status)">Pending</span></span><span style="width:48px"></span></header><div class="detail-body"><div class="detail-identity"><div class="detail-ref"><span class="stop-index mono" x-text="String(selected.index).padStart(2,'0')">02</span><span class="mono" x-text="selected.reference">TV-300002</span></div><h1 x-text="selected.customer_name">Silverline Supplies</h1><p class="detail-address"><span x-text="street">215 Pitt St</span><span x-text="locality">Newtown NSW</span></p></div><div class="data-row"><span class="label">{icon('clock')}Delivery window</span><span class="value mono" x-text="selected.time_window?.replace('-','–')">08:00–10:00</span></div><div class="data-row"><span class="label">{icon('location')}Location</span><span class="value">Sydney, NSW</span></div><div class="coordinate-row"><span class="mono" x-text="selected.latitude?.toFixed(6)+', '+selected.longitude?.toFixed(6)">-33.909712, 151.162838</span></div><div class="data-row"><span class="label">{icon('cloud')}Sync status</span><span class="value" :style="isQueued(selectedId)?'color:var(--warn)':''" x-text="isQueued(selectedId)?(syncing?'Sending update':'Waiting to sync'):selected.syncedAt?'Synced':'No pending update'">No pending update</span></div><div class="final-result" x-cloak x-show="selected.status !== 'pending'" :class="{{failed:selected.status === 'failed'}}"><span x-show="selected.status==='completed'">{icon('checkcircle')}</span><span x-show="selected.status==='failed'">{icon('warning')}</span><div><h3 x-text="selected.status==='completed'?'Delivery completed':'Delivery failed'"></h3><p x-show="selected.status === 'failed'" x-text="selected.failureReason || 'No reason provided in the source record.'"></p><p x-text="selected.updatedAt?'Recorded at '+time(selected.updatedAt):'Imported delivery record'"></p></div></div><div class="detail-trust" x-show="selected.status === 'pending'">{icon('shield')}<span x-text="online?'Changes are saved before syncing.':'You can finish this stop offline. Your update will be saved and sent when online.'">Changes are saved before syncing.</span></div><div x-cloak x-show="saveError" class="save-error" role="alert" x-text="saveError"></div></div><footer class="detail-footer"><div x-show="selected.status === 'pending'"><button class="primary complete-delivery" @click="update('completed')">{icon('check')}Complete delivery</button><button class="secondary fail-delivery" x-ref="failTrigger" @click="openFailure()">{icon('warning')}Report a failed delivery</button></div><div x-cloak x-show="selected.status !== 'pending'"><button class="primary" @click="closeDetail()">Back to stops {icon('arrow')}</button><p class="muted" style="font-size:13px;text-align:center;margin-top:16px">This delivery status is final.</p></div><span class="home-indicator"></span></footer></section>'''

reason_options=''.join(f'''<button class="reason-option" :class="{{chosen:reason === '{r}'}}" @click="reason='{r}';reasonError=false" :aria-pressed="reason === '{r}'" {('x-ref="reasonFirst"' if i==0 else '')}><span class="radio" aria-hidden="true"></span>{r}</button>''' for i,r in enumerate(['Recipient unavailable','Business closed','Address not found','Other']))
failure=f'''<div class="scrim" x-cloak x-show="failureOpen" x-transition.opacity.duration.190ms @click.self="failureOpen=false"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="failure-title" x-show="failureOpen" x-transition:enter-start="translate-y-full" x-transition:enter-end="translate-y-0" @keydown.tab="trapSheet($event)"><div class="sheet-grip" aria-hidden="true"></div><div class="sheet-top"><h2 id="failure-title">Report failed delivery</h2><button class="icon-button" @click="failureOpen=false" aria-label="Close failure form">{icon('close')}</button></div><p class="sheet-sub" x-text="selected.customer_name+' · '+selected.reference">Silverline Supplies · TV-300002</p><span class="reason-label">What happened? <span class="muted">(required)</span></span><div class="reasons">{reason_options}</div><label class="reason-label" for="failure-note" x-text="reason === 'Other'?'Describe the reason (required)':'Add a note (optional)'">Add a note (optional)</label><textarea id="failure-note" x-ref="failureNote" x-model="note" @input="reasonError=false" placeholder="Add useful details for the dispatcher" :aria-invalid="reasonError" aria-describedby="reason-error"></textarea><p class="field-error" x-cloak x-show="reasonError" id="reason-error" role="alert" x-text="reason === 'Other'?'Enter a reason to continue.':'Choose a reason to continue.'">Choose a reason to continue.</p><p class="terminal-note">This will mark the stop as failed. The delivery status cannot be changed afterwards.</p><button class="primary danger-button confirm-failure" @click="update('failed')">{icon('warning')}Mark delivery as failed</button></section></div>'''

for variant,view,name in [('a',list_view,'Dispatch list'),('b',focus_view,'Stop workspace'),('c',windows_view,'Time windows')]:
    filename={'a':'index.html','b':'focus.html','c':'windows.html'}[variant]
    doc=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{name} · Transvirtual</title><link rel="icon" href="data:,"><link rel="stylesheet" href="assets/app.css"><script>window.DELIVERIES={json.dumps(DATA)};</script><script src="assets/app.js"></script><script defer src="vendor/alpine.min.js"></script></head><body data-variant="{variant}"><main class="phone" x-data="deliveryApp" @keydown.escape.window="escape()"><div class="system-bar" aria-hidden="true"><span>9:41</span><span class="system-icons">{icon('signal')}{icon('battery')}</span></div><header class="app-top"><span class="brand"><span class="brand-mark">{icon('box')}</span>Transvirtual</span><button class="connection main-toggle" :class="{{offline:!online}}" role="switch" :aria-checked="online" aria-label="Online connection" @click="toggleOnline()"><span class="connection-dot"></span><span x-text="online?'Online':'Offline'">Online</span><span class="switch on" :class="{{on:online}}"></span></button></header>{view}{sync_view}<div class="offline-note" x-cloak x-show="!online">{icon('offline')}<span>Offline <span aria-hidden="true">·</span> your updates are saved</span></div><nav class="bottom-nav" aria-label="Main navigation"><button :class="{{active:page === 'stops'}}" :aria-current="page === 'stops'?'page':false" @click="page='stops'" class="stops-nav">{icon('list')}Stops <span class="mono" x-text="count('pending')">24</span></button><button :class="{{active:page === 'sync'}}" :aria-current="page === 'sync'?'page':false" @click="page='sync'" class="sync-nav">{icon('sync')}Sync <span class="nav-count" x-cloak x-show="queue.length" x-text="queue.length"></span><span x-show="!queue.length" style="color:var(--success)">{icon('check')}</span></button><span class="home-indicator"></span></nav>{detail}{failure}<div class="toast" role="status" aria-live="polite" x-cloak x-show="toast" x-transition.opacity.duration.180ms>{icon('checkcircle')}<span x-text="toast"></span></div></main></body></html>'''
    doc=doc.replace('x-transition:enter="" x-transition:enter-start="" x-transition:enter-end="" x-transition:leave=""','x-transition:enter="detail-enter" x-transition:enter-start="detail-start" x-transition:enter-end="detail-end" x-transition:leave="detail-leave" x-transition:leave-start="detail-end" x-transition:leave-end="detail-start"').replace('x-transition:enter.duration.320ms x-transition:leave.duration.190ms','')
    doc=doc.replace('x-transition:enter-start="translate-y-full" x-transition:enter-end="translate-y-0"','x-transition:enter="sheet-enter" x-transition:enter-start="sheet-start" x-transition:enter-end="sheet-end" x-transition:leave="sheet-leave" x-transition:leave-start="sheet-end" x-transition:leave-end="sheet-start"')
    doc=doc.replace('<p class="terminal-note">','<div x-cloak x-show="saveError" class="save-error" style="margin:12px 0" role="alert" x-text="saveError"></div><p class="terminal-note">')
    doc=doc.replace('<span>CSV order</span>','<span>By reference</span>').replace('>Done</button>','>Completed</button>')
    doc=refine(doc,variant,DATA,ICON)
    (ROOT/filename).write_text(doc)
manifest={'schemaVersion':1,'lang':'zh','project':'Transvirtual · Driver delivery','brief':'工具风司机配送 App：30 个真实站点、终态更新、离线保存和可见同步队列。三种方案的字体、颜色和交互规范相同，比较信息组织和主要操作的位置。','round':'01 · 版式方案','candidates':[]}
for variant,name,concept,traits,file in [
    ('a','清单优先','像一份随手可查的配送清单，先看清任务，再处理当前站点。',['推荐 · 30 个站点便于扫描','滑块筛选 / 地址优先 / 详情底部操作','离线状态轻量，待同步独立表达'],'index.html'),
    ('b','当前站点优先','把一站配送的对象、时间窗和完成操作集中在拇指可触达的工作台。',['完成按钮常驻当前任务','处理后主动选择另一站','适合一站一站连续作业'],'focus.html'),
    ('c','时间窗优先','把站点归到交付时间窗，先判断这一批，再进入单个站点。',['按 CSV 时间窗分组','状态与时间窗双层筛选','适合按批次查漏补缺'],'windows.html')]:
    manifest['candidates'].append({'id':variant,'name':name,'concept':concept,'typography':'Inter Variable · 精细字重和光学字号 / 正文 14–18px / 表格数字','palette':['#ff6b38','#30271f','#fff8ed','#fff'],'traits':traits,'kind':'html','source':file,'interactive':True})
manifest['project']='Transvirtual · 第二版'
manifest['brief']='鲜明橙色 × 奶油白。重做构图与字体层级，把任务信息更早放到首屏；首页、详情、失败表单与同步队列使用一致的视觉语言。左边是第一版，右边可直接操作新版。'
manifest['round']='02 · 重新设计'
manifest['candidates']=[{'id':'before','name':'第一版','concept':'之前的版式，保留作为对照。','typography':'系统无衬线 · 粗标题 / 蓝色操作','palette':['#182332','#2458e0','#f6f7f9'],'traits':['之前的设计'],'kind':'html','source':'archive/round1/index.html','baseline':True,'interactive':True}, {'id':'refined','name':'橙色作业清单','concept':'温暖、鲜明、有秩序。让每一条配送任务和每一次操作都清楚可读。','typography':'Inter Variable · 标题 31–39px / 正文 14–18px / 克制字重与光学间距','palette':['#ff6b38','#30271f','#fff8ed','#fff'],'traits':['新版 · 明确橙色识别','合并页头 / 搜索收起 / 信息前移','任务刻度 / 悬浮操作坞 / 直接保存反馈'],'kind':'html','source':'index.html','interactive':True}]
map_failure=failure.replace('x-transition:enter-start="translate-y-full" x-transition:enter-end="translate-y-0"','x-transition:enter="sheet-enter" x-transition:enter-start="sheet-start" x-transition:enter-end="sheet-end" x-transition:leave="sheet-leave" x-transition:leave-start="sheet-end" x-transition:leave-end="sheet-start"')
map_failure=map_failure.replace('<p class="terminal-note">','<div x-cloak x-show="saveError" class="save-error" style="margin:12px 0" role="alert" x-text="saveError"></div><p class="terminal-note">')
(ROOT/'index.html').write_text(map_html(DATA,ICON,map_failure))
for legacy in ['focus.html','windows.html']:
    (ROOT/legacy).write_text('<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta http-equiv="refresh" content="0;url=index.html"><title>Delivery map</title></head><body><a href="index.html">Open delivery map</a></body></html>')
manifest.update(project='ocean delivery · 地图工作台',round='03 · 地图为基础',brief='地图是整个作业界面的基础：30 个站点按 CSV 坐标落点，标记表达配送状态；当前位置固定在站点附近。点选站点后展开底部任务卡，筛选、搜索和同步都在地图工作台完成。左边保留上一版，右边运行新版。')
